#include "sblr_ddl_drop_dictionary_runtime.hpp"
#include <algorithm>
#include <cstring>
namespace scratchbird::engine::sblr { namespace { using B=std::uint8_t; bool nz(const auto&a){for(auto v:a)if(v)return true;return false;} void put(std::vector<B>&o,std::uint64_t v,int n){for(int i=0;i<n;i++)o.push_back((B)(v>>(i*8)));} std::uint64_t get(const B*b,int n){std::uint64_t v=0;for(int i=0;i<n;i++)v|=(std::uint64_t)b[i]<<(i*8);return v;} std::vector<B> head(const char*m,int n){std::vector<B>o(m,m+4);o.push_back(1);o.push_back(0);put(o,n,2);o.insert(o.end(),n-8,0);return o;} bool valid(const B*b,std::size_t n,const char*m,int z){return b&&n==(std::size_t)z&&std::memcmp(b,m,4)==0&&b[4]==1;} std::array<B,32> digest(const B*b,std::size_t n){std::array<B,32>a{};for(std::size_t i=0;i<n;++i)a[i%32]=B(a[i%32]*33u+b[i]);return a;} }
std::vector<B> EncodeSblrDdlDropDictionaryRequestV1(const SblrDdlDropDictionaryRequestV1&x){if(!nz(x.receipt)||!x.occurrence||!x.dictionary_occurrence)return{};auto o=head("DDRQ",64);o.insert(o.end(),x.receipt.begin(),x.receipt.end());put(o,x.occurrence,8);put(o,x.dictionary_occurrence,4);o.insert(o.end(),20,0);return o;} bool DecodeSblrDdlDropDictionaryRequestV1(const B*b,std::size_t n,SblrDdlDropDictionaryRequestV1*x,std::string*q){if(!x||!valid(b,n,"DDRQ",64)){if(q)*q="DDRQ invalid";return false;}std::copy_n(b+16,16,x->receipt.begin());x->occurrence=get(b+32,8);x->dictionary_occurrence=get(b+40,4);return x->occurrence&&x->dictionary_occurrence;}
std::vector<B> EncodeSblrDdlDropDictionaryDescriptorV1(const SblrDdlDropDictionaryDescriptorV1&x,bool op){if(!nz(x.body)||!x.availability)return{};auto o=head(op?"DDRO":"DDDD",488);o.insert(o.end(),x.body.begin(),x.body.end());auto e=digest(o.data()+16,400);if(nz(x.evidence)&&e!=x.evidence)return{};o.insert(o.end(),e.begin(),e.end());put(o,x.availability,8);o.insert(o.end(),32,0);return o;} bool DecodeSblrDdlDropDictionaryDescriptorV1(const B*b,std::size_t n,SblrDdlDropDictionaryDescriptorV1*x,std::string*q,bool op){if(!x||!valid(b,n,op?"DDRO":"DDDD",488)||std::any_of(b+456,b+488,[](B v){return v;})){if(q)*q="DDRO/DDDD invalid";return false;}std::copy_n(b+16,400,x->body.begin());std::copy_n(b+416,32,x->evidence.begin());x->availability=get(b+448,8);return x->availability&&nz(x->evidence);}
std::vector<B> EncodeSblrDdlDropDictionaryResultV1(const SblrDdlDropDictionaryResultV1&x){if(!nz(x.body)||!x.availability||!nz(x.publication_barrier))return{};auto o=head("DDRS",320);o.insert(o.end(),x.body.begin(),x.body.end());auto e=digest(o.data()+16,248);if(nz(x.evidence)&&e!=x.evidence)return{};o.insert(o.end(),e.begin(),e.end());put(o,x.availability,8);o.insert(o.end(),x.publication_barrier.begin(),x.publication_barrier.end());return o;} bool DecodeSblrDdlDropDictionaryResultV1(const B*b,std::size_t n,SblrDdlDropDictionaryResultV1*x,std::string*q){if(!x||!valid(b,n,"DDRS",320)){if(q)*q="DDRS invalid";return false;}std::copy_n(b+16,248,x->body.begin());std::copy_n(b+264,32,x->evidence.begin());x->availability=get(b+296,8);std::copy_n(b+304,16,x->publication_barrier.begin());return x->availability&&nz(x->evidence)&&nz(x->publication_barrier);}}
